schema_definition:
CREATE TABLE hr_employees (
    employee_id NUMBER(6) PRIMARY KEY,
    first_name VARCHAR2(20),
    salary NUMBER(8,2),
    department_id NUMBER(4)
);

CREATE TABLE hr_departments (
    department_id NUMBER(4) PRIMARY KEY,
    department_name VARCHAR2(30)
);

