solution_code.oracle:
CREATE OR REPLACE PROCEDURE calculate_dept_bonus (
    p_dept_id IN NUMBER,
    p_total_bonus OUT NUMBER
) IS
    v_sum NUMBER(10,2) := 0;
BEGIN
    SELECT NVL(SUM(salary * 0.10), 0) INTO v_sum FROM hr_employees WHERE department_id = p_dept_id;
    p_total_bonus := v_sum;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        p_total_bonus := 0;
    WHEN OTHERS THEN
        p_total_bonus := -1;
END;
